import { defineConfig, mergeConfig } from 'vitest/config';
import type { CoverageOptions } from 'vitest/node';
import viteConfig from './vite.config';

// The source files the integration suite answers for. The unit suite answers
// for every other one, so a new file belongs to it until it is listed here.
export const integrationOnly: string[] = [];

// Each suite must reach this in every file it answers for, on its own.
// routeTree.gen.ts is generated by the router plugin, and main.tsx only
// mounts the app the tests render.
export const coverage = {
  provider: 'v8',
  exclude: [
    '**/*.test.{ts,tsx}',
    'src/**/*.d.ts',
    'src/main.tsx',
    'src/routeTree.gen.ts',
  ],
  thresholds: {
    lines: 90,
    functions: 90,
    branches: 90,
    statements: 90,
    perFile: true,
  },
} satisfies CoverageOptions;

// The unit suite: *.test.ts(x) in jsdom, no browser, with fetch stubbed, and
// the build's own modules beside vite.config.ts. The root vitest.config.ts
// runs it with the integration suite. The Vite config is merged in, so the
// router plugin generates src/routeTree.gen.ts here too.
export default mergeConfig(
  viteConfig({ mode: 'test', command: 'serve' }),
  defineConfig({
    test: {
      name: 'web/unit',
      environment: 'jsdom',
      include: ['src/**/*.test.{ts,tsx}', '*.test.ts'],
      exclude: ['src/**/*.integration.test.{ts,tsx}'],
      setupFiles: ['./vitest.setup.ts'],
      coverage: {
        ...coverage,
        include: [
          'src/**/*.{ts,tsx}',
          'content-security-policy.ts',
          'settings.ts',
        ],
        exclude: [...coverage.exclude, ...integrationOnly],
      },
    },
  }),
);
